// Converts state-machine events into user-facing alerts, with repeat
// suppression so a flapping condition cannot flood the user.
// Hardware independent.
#pragma once

#include "core/Types.h"
#include "motor/MotorStateMachine.h"

namespace wintek {

enum class AlertType : uint8_t {
  TANK_FULL = 0,
  MOTOR_STARTED,
  MOTOR_STOPPED,
  SENSOR_FAULT,
  MOTOR_OVERLOAD,
  EXCESSIVE_RUNTIME,
  POWER_RESTORED,
  OVERFLOW_CUTOFF,
  CONTACTOR_FAULT,
  NO_LEVEL_RISE,
  EMERGENCY_STOP,
  LOCAL_PANEL_FAULT,
  FAULT_CLEARED,
  RUNTIME_WARNING,
  // DEVICE_OFFLINE is generated by the backend from the MQTT Last Will.
};

enum class AlertSeverity : uint8_t { INFO = 0, WARNING, CRITICAL };

const char* toString(AlertType t);
const char* toString(AlertSeverity s);

struct Alert {
  AlertType type = AlertType::MOTOR_STARTED;
  AlertSeverity severity = AlertSeverity::INFO;
  uint32_t seq = 0;
  uint32_t atMs = 0;
  FaultCode fault = FaultCode::NONE;
  StartReason startReason = StartReason::NONE;
  StopReason stopReason = StopReason::NONE;
  uint8_t levelPercent = 0;
  uint32_t runtimeMs = 0;
  uint16_t suppressedRepeats = 0;  // identical alerts swallowed since the last one
};

class AlertManager {
 public:
  static constexpr uint32_t kRepeatSuppressMs = 10UL * 60UL * 1000UL;

  // Returns true when `out` holds an alert to deliver.
  bool fromEvent(const MachineEvent& e, Alert& out);
  bool raise(AlertType t, FaultCode f, uint32_t nowMs, uint8_t level, Alert& out);

 private:
  bool admit(Alert& a);
  static AlertType alertForFault(FaultCode f);
  static AlertSeverity severityFor(AlertType t);

  struct Memo {
    bool used = false;
    AlertType type = AlertType::MOTOR_STARTED;
    FaultCode fault = FaultCode::NONE;
    uint32_t lastMs = 0;
    uint16_t suppressed = 0;
  };
  Memo memo_[16];
  uint32_t seq_ = 0;
};

}  // namespace wintek
